// Hand-written (not generated by swagger-codegen). Listed in .swagger-codegen-ignore
// so it survives regeneration.

using System;
using System.Net.Http;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Calira.Api.Model;

namespace Calira.Api.Client
{
    /// <summary>
    /// Small helpers for things the generated client cannot do from the API spec alone.
    /// </summary>
    public static class CaliraHelpers
    {
        private static readonly HttpClient Http = new HttpClient();

        /// <summary>
        /// Convert a time to the form the Calira API expects: UTC, whole seconds.
        /// Use this for every start_time / end_time you send, e.g.
        /// <code>StartTime = CaliraHelpers.ToApiTime(DateTime.Now.AddDays(1))</code>
        /// (Times without a time zone, or with more than 3 decimal places, are rejected.)
        /// </summary>
        public static DateTime ToApiTime(DateTime time)
        {
            var utc = time.Kind == DateTimeKind.Unspecified
                ? DateTime.SpecifyKind(time, DateTimeKind.Utc)   // assume UTC if no kind was given
                : time.ToUniversalTime();
            return new DateTime(utc.Year, utc.Month, utc.Day, utc.Hour, utc.Minute, utc.Second, DateTimeKind.Utc);
        }

        /// <summary>
        /// The checksum POST /uploads needs: the MD5 hash of the file, base64-encoded.
        /// </summary>
        public static string ComputeChecksum(byte[] fileBytes)
        {
            using (var md5 = MD5.Create())
            {
                return Convert.ToBase64String(md5.ComputeHash(fileBytes));
            }
        }

        /// <summary>
        /// Step 2 of a file upload: send the file bytes to the direct-upload target returned by
        /// <see cref="Api.UploadsApi.RegisterUpload"/>. Uses the headers Calira supplied, not the Bearer token.
        /// After this succeeds, use the upload's SignedId in an equipment or booking note request.
        /// </summary>
        public static async Task UploadFileBytesAsync(UploadDirectUploadTarget directUpload, byte[] fileBytes)
        {
            using (var request = new HttpRequestMessage(HttpMethod.Put, directUpload.Url))
            {
                request.Content = new ByteArrayContent(fileBytes);
                if (directUpload.Headers != null)
                {
                    foreach (var header in directUpload.Headers)
                    {
                        // Content headers (e.g. Content-Type, Content-MD5) belong on the content.
                        if (!request.Headers.TryAddWithoutValidation(header.Key, header.Value))
                            request.Content.Headers.TryAddWithoutValidation(header.Key, header.Value);
                    }
                }

                using (var response = await Http.SendAsync(request).ConfigureAwait(false))
                {
                    if (!response.IsSuccessStatusCode)
                    {
                        var body = await response.Content.ReadAsStringAsync().ConfigureAwait(false);
                        throw new ApiException((int)response.StatusCode, "File upload failed: " + body, body);
                    }
                }
            }
        }
    }
}
